-- Generated by tools/GenerateRptViews.py; edit the generator, not this file.
-- One row per payment the company made on bills or expense reports, voided ones included. Needs ap.view.
CREATE VIEW rpt.BillPayment
AS
SELECT
    bp.Id AS BillPaymentId,
    bp.PaymentDate AS PaymentDate,
    bp.VendorId AS VendorId,
    COALESCE(v.Name, u.DisplayName) AS PayeeName,
    pm.Name AS PaymentMethod,
    bp.ReferenceNumber AS ReferenceNumber,
    bp.Amount AS Amount,
    bp.AmountApplied AS AmountApplied,
    bp.UnappliedAmount AS UnappliedAmount,
    CONVERT(BIT, IIF(bp.VoidedAt IS NULL, 0, 1)) AS IsVoided
FROM ap.BillPay AS bp
JOIN lkp.PaymentMethod AS pm ON pm.TenantId = bp.TenantId AND pm.Id = bp.PaymentMethodId
LEFT JOIN ap.Vendor AS v ON v.TenantId = bp.TenantId AND v.Id = bp.VendorId
LEFT JOIN sec.AppUser AS u ON u.TenantId = bp.TenantId AND u.Id = bp.PayeeUserId
WHERE EXISTS (SELECT 1 FROM sec.fn_UserHasPermission(bp.TenantId, CONVERT(INT, SESSION_CONTEXT(N'UserId')), 'ap.view'));
GO
